package com.example.data.quran

/**
 * Explicit verification provenance for Quranic linguistic (I'rab & Sarf) entries.
 * Never mixes unverified output with verified classical grammatical/morphological scholarship.
 */
enum class LinguisticVerificationStatus(val labelAr: String, val labelEn: String) {
    VERIFIED_SCHOLARLY_CATALOG(
        "مرجع نحوي وصرفي موثّق (الجدول في إعراب القرآن وصرفه — محمود صافي / الدرويش)",
        "Verified Classical Reference (Al-Jadwal — M. Safi / Al-Darwish)"
    ),
    IMPORTED_LOCAL_PACK(
        "حزمة لغوية محلية مستوردة",
        "Imported Offline Linguistic Pack"
    ),
    UNAVAILABLE(
        "التحليل النحوي/الصرفي الموثّق غير متوفر لهذه الآية حالياً",
        "Verified I'rab / Sarf analysis is currently unavailable for this Ayah"
    )
}

/**
 * Grammatical analysis (الإعراب) for a single immutable Quranic word.
 */
data class WordIrabEntry(
    val grammaticalRoleAr: String,     // e.g. "مبتدأ مرفوع", "فعل أمر", "جار ومجرور"
    val grammaticalRoleEn: String,     // e.g. "Nominative Subject", "Imperative Verb"
    val caseEndingAr: String,          // e.g. "علامة رفعه الضمة الظاهرة"
    val relationshipAr: String = "",   // e.g. "متعلق بمحذوف خبر مقدم"
    val explanationAr: String          // Detailed classical grammatical note
)

/**
 * Morphological analysis (الصرف) for a single immutable Quranic word.
 */
data class WordSarfEntry(
    val rootAr: String,                // الجذر e.g. "ح م د" or "—" for indeclinable particles
    val patternAr: String,             // الوزن الصرفي e.g. "فَعْل", "فَعِيل", "فَعْلَان"
    val partOfSpeechAr: String,        // نوع الكلمة e.g. "اسم / مصدر", "فعل مضارع", "حرف جر"
    val partOfSpeechEn: String,        // e.g. "Noun / Verbal Noun", "Imperfect Verb", "Preposition"
    val verbFormAr: String = "—",      // المجرد والمزيد e.g. "ثلاثي مجرد", "مزيد بالهمزة (أَفْعَلَ)"
    val tenseAr: String = "—",         // الزمن e.g. "ماضٍ", "مضارع", "أمر", "—"
    val numberGenderAr: String = "—",  // الإفراد والتثنية والجمع e.g. "مفرد مذكر", "جمع مذكر سالم"
    val derivationAr: String = "—",    // الاشتقاق e.g. "صفة مشبهة", "اسم فاعل", "مصدر", "جامد"
    val notesAr: String = ""           // Additional morphological notes (إعلال، إبدال، إدغام)
)

/**
 * Word-level linguistic annotation linked strictly to `(surahNumber, ayahNumber, wordPosition)`
 * while keeping the exact Quranic Uthmani word immutable.
 */
data class WordLinguisticAnalysis(
    val surahNumber: Int,
    val ayahNumber: Int,
    val wordPosition: Int,
    val exactUthmaniWord: String,
    val irab: WordIrabEntry?,
    val sarf: WordSarfEntry?
)

/**
 * Complete structured linguistic record for a single Ayah.
 * Keeps `exactUthmaniAyahText` immutable and strictly separated from linguistic annotations and Tafsir.
 */
data class AyahLinguisticAnalysis(
    val surahNumber: Int,
    val ayahNumber: Int,
    val exactUthmaniAyahText: String,
    val sentenceSummaryAr: String,
    val words: List<WordLinguisticAnalysis>,
    val tafsirMuyassarAr: String = "",
    val sourceAr: String,
    val sourceEn: String,
    val verificationStatus: LinguisticVerificationStatus
) {
    val hasVerifiedIrab: Boolean
        get() = verificationStatus != LinguisticVerificationStatus.UNAVAILABLE && words.any { it.irab != null }

    val hasVerifiedSarf: Boolean
        get() = verificationStatus != LinguisticVerificationStatus.UNAVAILABLE && words.any { it.sarf != null }
}

